@ Timer0 reload values (prescaler /64) for PCM rate index 0..19
	.global PcmRateTable
PcmRateTable:
	.hword 0xFFFA, 0xFFF8, 0xFFF4, 0xFFF0, 0xFFEF, 0xFFEE, 0xFFED, 0xFFEC
	.hword 0xFFEB, 0xFFEA, 0xFFE9, 0xFFE8, 0xFFE7, 0xFFE6, 0xFFE5, 0xFFE4
	.hword 0xFFE3, 0xFFE2, 0xFFE1, 0xFFE0

@ voice -> L|R active bits
	.global PcmVoiceBitsLR
PcmVoiceBitsLR:
	.word 0x00000011, 0x00000022, 0x00000044, 0x00000088

@ voice -> left (FIFO A) active bit
	.global PcmVoiceBitsL
PcmVoiceBitsL:
	.word 0x00000001, 0x00000002, 0x00000004, 0x00000008

@ voice -> right (FIFO B) active bit
	.global PcmVoiceBitsR
PcmVoiceBitsR:
	.word 0x00000010, 0x00000020, 0x00000040, 0x00000080

@ voice -> mask clearing both bits
	.global PcmVoiceClearMasks
PcmVoiceClearMasks:
	.word 0xFFFFFFEE, 0xFFFFFFDD, 0xFFFFFFBB, 0xFFFFFF77

	.section .rodata.kr_sound_cmds,"a",%progbits
	.balign 4

